package com.gym.management.entity;
import jakarta.persistence.*;import java.time.*;
@Entity @Table(name="member_notifications",uniqueConstraints=@UniqueConstraint(name="uk_notification_dedupe",columnNames="dedupe_key"),indexes=@Index(name="idx_notification_member_created",columnList="member_id,created_at"))
public class MemberNotification{
 @Id @GeneratedValue(strategy=GenerationType.IDENTITY)Long id;@ManyToOne(fetch=FetchType.LAZY,optional=false)@JoinColumn(name="member_id",nullable=false)Member member;@ManyToOne(fetch=FetchType.LAZY)@JoinColumn(name="announcement_id")GymAnnouncement announcement;@Column(nullable=false,length=32)String category;@Column(nullable=false,length=120)String title;@Column(nullable=false,length=1000)String message;@Column(nullable=false)LocalDateTime createdAt;LocalDateTime readAt;@Column(name="dedupe_key",nullable=false,length=180)String dedupeKey;
 protected MemberNotification(){}public MemberNotification(Member m,String category,String title,String message,String key){this(m,null,category,title,message,key);}public MemberNotification(Member m,GymAnnouncement announcement,String category,String title,String message,String key){member=m;this.announcement=announcement;this.category=category;this.title=title;this.message=message;dedupeKey=key;createdAt=LocalDateTime.now();}public Long getId(){return id;}public Member getMember(){return member;}public GymAnnouncement getAnnouncement(){return announcement;}public String getCategory(){return category;}public String getTitle(){return title;}public String getMessage(){return message;}public String getDedupeKey(){return dedupeKey;}public LocalDateTime getCreatedAt(){return createdAt;}public LocalDateTime getReadAt(){return readAt;}public boolean isRead(){return readAt!=null;}public void markRead(){if(readAt==null)readAt=LocalDateTime.now();}
}
